-- SSS: dil başına 5 ek soru (toplam 8)
INSERT INTO faqs (id, locale, question, answer, sort_order) VALUES
  ('faq_4', 'en', 'Is Resumer free to use?', 'You can start for free with limited AI credits. Resumer Pro unlocks more monthly credits for analysis, job tailoring and translation.', 4),
  ('faq_5', 'en', 'What is ATS compatibility?', 'ATS (Applicant Tracking System) software screens resumes before a recruiter sees them. Resumer checks keywords, structure and formatting so your CV is easier for ATS tools to read.', 5),
  ('faq_6', 'en', 'How do I tailor my CV to a job posting?', 'Open Adapt to a job, paste the job posting link, pick a CV and let AI suggest targeted changes. Review the suggestions, apply the ones you want, then save.', 6),
  ('faq_7', 'en', 'Can I translate my CV into another language?', 'Yes. Choose Translate CV, pick the target language and options, then save the translated copy to My CVs. Headings and content follow the new language.', 7),
  ('faq_8', 'en', 'How do I manage or cancel my subscription?', 'Subscriptions are managed through the App Store or Google Play account that you used to subscribe. You can change or cancel there at any time.', 8),

  ('faq_4_tr', 'tr', 'Resumer ücretsiz mi?', 'Sınırlı AI kredisiyle ücretsiz başlayabilirsiniz. Resumer Pro, analiz, ilana uyarlama ve çeviri için aylık daha fazla kredi açar.', 4),
  ('faq_5_tr', 'tr', 'ATS uyumluluğu nedir?', 'ATS (Aday Takip Sistemi), özgeçmişleri işveren görmeden tarar. Resumer; anahtar kelime, yapı ve biçimi kontrol ederek CV''nizin ATS tarafından daha kolay okunmasını sağlar.', 5),
  ('faq_6_tr', 'tr', 'CV''mi iş ilanına nasıl uyarlarım?', 'İlana göre uyarla''yı açın, ilan bağlantısını yapıştırın, bir CV seçin ve yapay zekânın önerilerini inceleyin. İstediklerinizi uygulayıp kaydedin.', 6),
  ('faq_7_tr', 'tr', 'CV''mi başka bir dile çevirebilir miyim?', 'Evet. CV Çevir''i seçin, hedef dili ve seçenekleri belirleyin; çevrilen kopya CV''lerime kaydedilir. Başlıklar ve içerik yeni dili izler.', 7),
  ('faq_8_tr', 'tr', 'Aboneliğimi nasıl yönetir veya iptal ederim?', 'Abonelikler, satın aldığınız App Store veya Google Play hesabından yönetilir. Oradan istediğiniz zaman değiştirebilir veya iptal edebilirsiniz.', 8),

  ('faq_4_de', 'de', 'Ist Resumer kostenlos?', 'Sie können mit begrenzten KI-Credits kostenlos starten. Resumer Pro schaltet monatlich mehr Credits für Analyse, Stellenanpassung und Übersetzung frei.', 4),
  ('faq_5_de', 'de', 'Was bedeutet ATS-Kompatibilität?', 'ATS-Software filtert Lebensläufe, bevor Recruiter sie sehen. Resumer prüft Keywords, Struktur und Format, damit Ihr CV für ATS besser lesbar ist.', 5),
  ('faq_6_de', 'de', 'Wie passe ich meinen CV an eine Stellenanzeige an?', 'Öffnen Sie „An Stelle anpassen“, fügen Sie den Stellenlink ein, wählen Sie einen CV und prüfen Sie die KI-Vorschläge. Gewünschte Änderungen anwenden und speichern.', 6),
  ('faq_7_de', 'de', 'Kann ich meinen CV in eine andere Sprache übersetzen?', 'Ja. Wählen Sie CV übersetzen, Zielsprache und Optionen; die Übersetzung wird unter Meine CVs gespeichert. Überschriften und Inhalt folgen der neuen Sprache.', 7),
  ('faq_8_de', 'de', 'Wie verwalte oder kündige ich mein Abo?', 'Abos werden über das App-Store- oder Google-Play-Konto verwaltet, mit dem Sie abonniert haben. Dort können Sie jederzeit ändern oder kündigen.', 8),

  ('faq_4_it', 'it', 'Resumer è gratis?', 'Puoi iniziare gratis con crediti IA limitati. Resumer Pro sblocca più crediti mensili per analisi, adattamento e traduzione.', 4),
  ('faq_5_it', 'it', 'Cos''è la compatibilità ATS?', 'I sistemi ATS filtrano i CV prima dei recruiter. Resumer controlla parole chiave, struttura e formato così il CV è più leggibile dagli ATS.', 5),
  ('faq_6_it', 'it', 'Come adatto il CV a un annuncio?', 'Apri Adatta all''annuncio, incolla il link, scegli un CV e rivedi i suggerimenti IA. Applica quelli che vuoi e salva.', 6),
  ('faq_7_it', 'it', 'Posso tradurre il CV in un''altra lingua?', 'Sì. Scegli Traduci CV, la lingua e le opzioni; la copia tradotta va in I miei CV. Titoli e contenuto seguono la nuova lingua.', 7),
  ('faq_8_it', 'it', 'Come gestisco o annullo l''abbonamento?', 'Gli abbonamenti si gestiscono dall''App Store o Google Play usati per l''acquisto. Puoi modificare o annullare in qualsiasi momento.', 8),

  ('faq_4_fr', 'fr', 'Resumer est-il gratuit ?', 'Vous pouvez commencer gratuitement avec des crédits IA limités. Resumer Pro débloque plus de crédits mensuels pour l''analyse, l''adaptation et la traduction.', 4),
  ('faq_5_fr', 'fr', 'Qu''est-ce que la compatibilité ATS ?', 'Les ATS filtrent les CV avant les recruteurs. Resumer vérifie mots-clés, structure et format pour une meilleure lisibilité ATS.', 5),
  ('faq_6_fr', 'fr', 'Comment adapter mon CV à une offre ?', 'Ouvrez Adapter à une offre, collez le lien, choisissez un CV et examinez les suggestions IA. Appliquez celles voulues puis enregistrez.', 6),
  ('faq_7_fr', 'fr', 'Puis-je traduire mon CV ?', 'Oui. Choisissez Traduire le CV, la langue et les options ; la copie est enregistrée dans Mes CV. Titres et contenu suivent la nouvelle langue.', 7),
  ('faq_8_fr', 'fr', 'Comment gérer ou résilier mon abonnement ?', 'Les abonnements se gèrent via le compte App Store ou Google Play utilisé. Vous pouvez modifier ou résilier à tout moment.', 8),

  ('faq_4_es', 'es', '¿Resumer es gratis?', 'Puedes empezar gratis con créditos de IA limitados. Resumer Pro desbloquea más créditos mensuales para análisis, adaptación y traducción.', 4),
  ('faq_5_es', 'es', '¿Qué es la compatibilidad ATS?', 'Los ATS filtran currículums antes de que los vea un reclutador. Resumer revisa palabras clave, estructura y formato para que el CV sea más legible.', 5),
  ('faq_6_es', 'es', '¿Cómo adapto mi CV a una oferta?', 'Abre Adaptar a una oferta, pega el enlace, elige un CV y revisa las sugerencias de IA. Aplica las que quieras y guarda.', 6),
  ('faq_7_es', 'es', '¿Puedo traducir mi CV?', 'Sí. Elige Traducir CV, el idioma y opciones; la copia se guarda en Mis CV. Títulos y contenido siguen el nuevo idioma.', 7),
  ('faq_8_es', 'es', '¿Cómo gestiono o cancelo mi suscripción?', 'Las suscripciones se gestionan en la cuenta de App Store o Google Play. Puedes cambiar o cancelar en cualquier momento.', 8),

  ('faq_4_pt', 'pt', 'O Resumer é grátis?', 'Você pode começar de graça com créditos de IA limitados. O Resumer Pro libera mais créditos mensais para análise, adaptação e tradução.', 4),
  ('faq_5_pt', 'pt', 'O que é compatibilidade com ATS?', 'Sistemas ATS filtram currículos antes dos recrutadores. O Resumer verifica palavras-chave, estrutura e formatação para melhor leitura.', 5),
  ('faq_6_pt', 'pt', 'Como adapto meu CV a uma vaga?', 'Abra Adaptar a uma vaga, cole o link, escolha um CV e revise as sugestões de IA. Aplique as desejadas e salve.', 6),
  ('faq_7_pt', 'pt', 'Posso traduzir meu CV?', 'Sim. Escolha Traduzir CV, o idioma e opções; a cópia vai para Meus CVs. Títulos e conteúdo seguem o novo idioma.', 7),
  ('faq_8_pt', 'pt', 'Como gerencio ou cancelo a assinatura?', 'Assinaturas são gerenciadas na conta da App Store ou Google Play. Você pode alterar ou cancelar a qualquer momento.', 8),

  ('faq_4_ru', 'ru', 'Resumer бесплатен?', 'Можно начать бесплатно с ограниченными ИИ-кредитами. Resumer Pro даёт больше кредитов в месяц на анализ, адаптацию и перевод.', 4),
  ('faq_5_ru', 'ru', 'Что такое совместимость с ATS?', 'ATS отсеивает резюме до рекрутера. Resumer проверяет ключевые слова, структуру и формат, чтобы CV лучше читалось системами.', 5),
  ('faq_6_ru', 'ru', 'Как адаптировать CV под вакансию?', 'Откройте «Адаптировать под вакансию», вставьте ссылку, выберите CV и просмотрите предложения ИИ. Примените нужные и сохраните.', 6),
  ('faq_7_ru', 'ru', 'Можно ли перевести CV?', 'Да. Выберите «Перевести CV», язык и параметры; копия сохранится в «Мои CV». Заголовки и текст будут на новом языке.', 7),
  ('faq_8_ru', 'ru', 'Как управлять или отменить подписку?', 'Подписки управляются через аккаунт App Store или Google Play. Изменить или отменить можно в любое время.', 8),

  ('faq_4_ja', 'ja', 'Resumerは無料ですか？', '制限付きAIクレジットで無料開始できます。Resumer Proは分析・求人適合・翻訳の月間クレジットを増やします。', 4),
  ('faq_5_ja', 'ja', 'ATS適合性とは？', 'ATSは採用担当者の前に履歴書をふるい分けます。Resumerはキーワード・構成・書式を確認し、ATSで読みやすくします。', 5),
  ('faq_6_ja', 'ja', '求人に合わせて履歴書を調整するには？', '「求人に合わせる」を開き、求人リンクを貼り、履歴書を選び、AI提案を確認します。必要なものを適用して保存します。', 6),
  ('faq_7_ja', 'ja', '履歴書を他言語に翻訳できますか？', 'はい。「履歴書を翻訳」で言語とオプションを選び、翻訳版は「マイ履歴書」に保存されます。見出しと内容は新言語に従います。', 7),
  ('faq_8_ja', 'ja', 'サブスクの管理・解約方法は？', '購読はApp StoreまたはGoogle Playアカウントで管理します。いつでも変更・解約できます。', 8),

  ('faq_4_ko', 'ko', 'Resumer는 무료인가요?', '제한된 AI 크레딧으로 무료로 시작할 수 있습니다. Resumer Pro는 분석·맞춤·번역용 월간 크레딧을 더 제공합니다.', 4),
  ('faq_5_ko', 'ko', 'ATS 적합성이란?', 'ATS는 채용 담당자 전에 이력서를 걸러냅니다. Resumer는 키워드·구조·형식을 확인해 ATS가 읽기 쉽게 만듭니다.', 5),
  ('faq_6_ko', 'ko', '채용 공고에 맞게 이력서를 조정하려면?', '채용 공고에 맞추기를 열고 링크를 붙여넣은 뒤 이력서를 선택하고 AI 제안을 검토하세요. 원하는 항목을 적용하고 저장합니다.', 6),
  ('faq_7_ko', 'ko', '이력서를 다른 언어로 번역할 수 있나요?', '네. 이력서 번역에서 언어와 옵션을 고르면 번역본이 내 이력서에 저장됩니다. 제목과 내용이 새 언어를 따릅니다.', 7),
  ('faq_8_ko', 'ko', '구독은 어떻게 관리하거나 해지하나요?', '구독은 App Store 또는 Google Play 계정에서 관리합니다. 언제든 변경하거나 해지할 수 있습니다.', 8),

  ('faq_4_zh', 'zh', 'Resumer 免费吗？', '可以用有限的 AI 积分免费开始。Resumer Pro 每月提供更多分析、职位定制和翻译积分。', 4),
  ('faq_5_zh', 'zh', '什么是 ATS 兼容性？', 'ATS 会在招聘方查看前筛选简历。Resumer 检查关键词、结构和格式，让简历更易被 ATS 读取。', 5),
  ('faq_6_zh', 'zh', '如何按职位优化简历？', '打开“按职位优化”，粘贴职位链接，选择简历并查看 AI 建议。应用需要的项后保存。', 6),
  ('faq_7_zh', 'zh', '可以把简历翻译成其他语言吗？', '可以。选择“翻译简历”、目标语言和选项，译文会保存到“我的简历”。标题和内容跟随新语言。', 7),
  ('faq_8_zh', 'zh', '如何管理或取消订阅？', '订阅通过用于购买的 App Store 或 Google Play 账户管理，可随时更改或取消。', 8),

  ('faq_4_hi', 'hi', 'क्या Resumer मुफ़्त है?', 'सीमित AI क्रेडिट के साथ मुफ़्त शुरू कर सकते हैं। Resumer Pro विश्लेषण, जॉब टेलरिंग और अनुवाद के लिए मासिक अधिक क्रेडिट देता है।', 4),
  ('faq_5_hi', 'hi', 'ATS अनुकूलता क्या है?', 'ATS सॉफ़्टवेयर भर्तीकर्ता से पहले रिज़्यूमे छानता है। Resumer कीवर्ड, संरचना और फ़ॉर्मैट जाँचता है ताकि CV ATS के लिए पठनीय हो।', 5),
  ('faq_6_hi', 'hi', 'नौकरी पोस्टिंग के अनुसार CV कैसे अनुकूलित करें?', 'जॉब के अनुसार अनुकूलित खोलें, लिंक पेस्ट करें, CV चुनें और AI सुझाव देखें। चाहे गए लागू कर सहेजें।', 6),
  ('faq_7_hi', 'hi', 'क्या मैं अपना CV दूसरी भाषा में अनुवाद कर सकता हूँ?', 'हाँ। CV अनुवाद चुनें, भाषा और विकल्प तय करें; अनुवादित कॉपी मेरे CV में सहेजी जाती है। शीर्षक और सामग्री नई भाषा में होते हैं।', 7),
  ('faq_8_hi', 'hi', 'सदस्यता कैसे प्रबंधित या रद्द करें?', 'सदस्यता App Store या Google Play खाते से प्रबंधित होती है। आप कभी भी बदल या रद्द कर सकते हैं।', 8);
